'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Float32Array = require( '@stdlib/array/float32' );
var Int32Array = require( '@stdlib/array/int32' );
var Complex128Array = require( '@stdlib/array/complex128' );
var descriptor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof descriptor, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an ndarray descriptor (row-major, generic)', function test( t ) {
	var expected;
	var actual;
	var dtype;
	var buf;
	var ord;
	var sh;
	var st;
	var o;

	dtype = 'generic';
	buf = [ 1, 2, 3, 4, 5 ];
	sh = [ 2, 2 ];
	st = [ 2, 1 ];
	o = 1;
	ord = 'row-major';

	expected = {
		'dtype': dtype,
		'data': buf,
		'shape': sh,
		'strides': st,
		'offset': o,
		'order': ord
	};
	actual = descriptor( dtype, buf, sh, st, o, ord );

	t.strictEqual( actual.data, expected.data, 'returns expected `data` value' );
	t.strictEqual( actual.dtype, expected.dtype, 'returns expected `dtype` value' );
	t.strictEqual( actual.shape, expected.shape, 'returns expected `shape` value' );
	t.strictEqual( actual.strides, expected.strides, 'returns expected `strides` value' );
	t.strictEqual( actual.offset, expected.offset, 'returns expected `offset` value' );
	t.strictEqual( actual.order, expected.order, 'returns expected `order` value' );
	t.end();
});

