tape( 'the function returns a plain object', function test( t ) {
	var actual;
	var buf;
	var sh;
	var st;

	buf = [ 1, 2, 3, 4 ];
	sh = [ 2, 2 ];
	st = [ 2, 1 ];

	actual = descriptor( 'generic', buf, sh, st, 0, 'row-major' );

	t.strictEqual( typeof actual, 'object', 'returns an object' );
	t.strictEqual( Object.getPrototypeOf( actual ), Object.prototype, 'has Object prototype' );
	t.end();
});

tape( 'the function returns an object having the expected properties in the expected order', function test( t ) {
	var actual;
	var keys;
	var buf;
	var sh;
	var st;

	buf = [ 1, 2, 3, 4 ];
	sh = [ 2, 2 ];
	st = [ 2, 1 ];

	actual = descriptor( 'generic', buf, sh, st, 0, 'row-major' );
	keys = Object.keys( actual );

	t.strictEqual( keys.length, 6, 'returns object with 6 properties' );
	t.strictEqual( keys[ 0 ], 'dtype', 'first key is `dtype`' );
	t.strictEqual( keys[ 1 ], 'data', 'second key is `data`' );
	t.strictEqual( keys[ 2 ], 'shape', 'third key is `shape`' );
	t.strictEqual( keys[ 3 ], 'strides', 'fourth key is `strides`' );
	t.strictEqual( keys[ 4 ], 'offset', 'fifth key is `offset`' );
	t.strictEqual( keys[ 5 ], 'order', 'sixth key is `order`' );
	t.end();
});

tape( 'the function returns a new object on each invocation', function test( t ) {
	var buf;
	var sh;
	var st;
	var r1;
	var r2;

	buf = [ 1, 2, 3, 4 ];
	sh = [ 2, 2 ];
	st = [ 2, 1 ];

	r1 = descriptor( 'generic', buf, sh, st, 0, 'row-major' );
	r2 = descriptor( 'generic', buf, sh, st, 0, 'row-major' );

	t.notEqual( r1, r2, 'returns a new object on each invocation' );
	t.strictEqual( r1.data, r2.data, 'shares `data` reference across invocations' );
	t.strictEqual( r1.shape, r2.shape, 'shares `shape` reference across invocations' );
	t.strictEqual( r1.strides, r2.strides, 'shares `strides` reference across invocations' );
	t.end();
});

